def ncr_modp(n, r, p):
    dp = [[0 for _ in range(r+1)] for _ in range(n+1)]
    dp[0][0] = 1

    for i in range(1, n+1):
        for j in range(min(i, r)+1):
            if j == 0 or j == i:
                dp[i][j] = 1
            else:
                dp[i][j] = (dp[i-1][j-1] + dp[i-1][j]) % p

    return dp[n][r]

