def pancake_sort(arr):
    def flip(arr, i):
        arr[:i+1] = arr[:i+1][::-1]

    def find_max(arr):
        max_idx = 0
        for i in range(len(arr)):
            if arr[i] > arr[max_idx]:
                max_idx = i
        return max_idx

    n = len(arr)
    for size in range(n, 1, -1):
        max_idx = find_max(arr[:size])
        if max_idx != size - 1:
            flip(arr, max_idx)
            flip(arr, size - 1)
    return arr

