def count_no_of_ways(n, k):
    if n == 1:
        return k
    elif n == 2:
        return k * k
    else:
        same_color = k
        different_color = k * (k - 1)
        for i in range(3, n + 1):
            same_color, different_color = different_color, (same_color + different_color) * (k - 1)
        return same_color + different_color

